def _remember(self, session_id: str, event: TradeEvent) -> None:
    buffer = self._history.get(session_id)
    if buffer is None:
        while len(self._history) >= MAX_TRACKED_SESSIONS:
            evicted, _ = self._history.popitem(last=False)
            self._seq.pop(evicted, None)
        buffer = deque(maxlen=HISTORY_LIMIT)
        self._history[session_id] = buffer
    else:
        self._history.move_to_end(session_id)
    buffer.append(event)

